source_checks.command:
test "$(git rev-parse HEAD)" = 022814a5566ebd49662fb58790eaedf1faf9e3b3
/data/cache/rustup/toolchains/stable-x86_64-unknown-linux-gnu/bin/rustfmt --edition 2024 --check crates/borsuk/src/sq8_page_authority.rs
git diff --check
git diff --exit-code -- Cargo.lock
test "$(git diff --name-only | LC_ALL=C sort)" = "$(printf '%s\n' crates/borsuk/Cargo.toml crates/borsuk/src/sq8_page_authority.rs | LC_ALL=C sort)"
perl -0777 -e '
use strict;
use warnings;
local $/;
open my $old_handle, "-|", "git", "show", "022814a5566ebd49662fb58790eaedf1faf9e3b3:crates/borsuk/src/sq8_page_authority.rs" or die $!;
my $old = <$old_handle>; close $old_handle or die "git show failed";
open my $new_handle, "<", "crates/borsuk/src/sq8_page_authority.rs" or die $!;
my $new = <$new_handle>;
$old =~ s/(\Q                let control = authority.verify_payload_sha2(page, page, payload);\E\n)/$1                control.map_err(|e| format!("{label} control setup: {e:?}"))?;\n/ or die "missing setup";
$old =~ s/\Qsemantic_match &= control == Ok(()) && candidate == control;\E/semantic_match \&= candidate == control;/ or die "missing comparison";
$old =~ s/(\Q                                if let Err(e) = black_box(result) {\E\n)\Q                                    semantic_match = false;\E/$1                                    if backend == 0 {\n                                        invalid = true;\n                                    } else {\n                                        semantic_match = false;\n                                    }/ or die "missing timed result";
die "unexpected authority diff" unless $old eq $new;
print "authority diff exactly limited to requested control failure classification\n";
'
git diff -- crates/borsuk/Cargo.toml crates/borsuk/src/sq8_page_authority.rs
wc -c Cargo.lock crates/borsuk/Cargo.toml crates/borsuk/src/sq8_page_authority.rs
sha256sum Cargo.lock crates/borsuk/Cargo.toml crates/borsuk/src/sq8_page_authority.rs
